-- 3.1 Also ensure mobile.demo user (if exists) has complete profile for testing
DO $$
DECLARE
    m_uid UUID;
BEGIN
    SELECT id INTO m_uid FROM users WHERE email = 'mobile.demo.20261011@stu.ptit.edu.vn';
    IF m_uid IS NOT NULL THEN
        INSERT INTO profiles (id, user_id, display_name, date_of_birth, gender, bio, photos, gpa, gpa_bucket, university_id, faculty_id, academic_year, purpose, profile_completed, gpa_visible, updated_at)
        VALUES (
            cast(md5('prof_' || m_uid::text) as uuid),
            m_uid,
            'Mobile Demo Tester',
            '2003-05-15',
            'male',
            'Tài khoản kiểm thử ứng dụng Android FwP PTIT.',
            '["https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=500"]'::jsonb,
            3.45,
            2,
            'a0000000-0000-0000-0000-000000000001',
            (SELECT id FROM faculties WHERE code = 'CNTT' LIMIT 1),
            3,
            'all',
            TRUE,
            TRUE,
            NOW()
        )
        ON CONFLICT (user_id) DO UPDATE SET profile_completed = TRUE, display_name = EXCLUDED.display_name;

        INSERT INTO preferences (id, user_id, gender_preference, min_age, max_age, max_distance_km, gpa_preference, max_gpa_tier_diff, same_university_only, updated_at)
        VALUES (cast(md5('pref_' || m_uid::text) as uuid), m_uid, 'all', 18, 30, 25, 'no_preference', 1, FALSE, NOW())
        ON CONFLICT (user_id) DO NOTHING;

        INSERT INTO user_locations (id, user_id, latitude, longitude, point, updated_at)
        VALUES (cast(md5('loc_' || m_uid::text) as uuid), m_uid, 20.9806, 105.7876, ST_SetSRID(ST_MakePoint(105.7876, 20.9806), 4326)::geography, NOW())
        ON CONFLICT (user_id) DO NOTHING;
    END IF;
END $$;

