-- Demo accounts are deliberately visible in Discover so a fresh demo has swipe cards.
UPDATE profiles p
SET discoverable = TRUE
FROM users u
WHERE u.id = p.user_id
  AND u.email LIKE 'demo.student%@stu.ptit.edu.vn'
  AND p.profile_completed = TRUE;

COMMIT;
